        answer: '$a+b=2\\sqrt{5}$，$ab=(\\sqrt{5})^{2}-2^{2}=1$，所以 $a^{2}-ab+b^{2}=(a+b)^{2}-3ab=(2\\sqrt{5})^{2}-3\\times 1=20-3=17$。',
