        answer: '由 $a^{2}-b^{2}=(a+b)(a-b)$ 得 $12=4(a-b)$，所以 $a-b=3$；再由 $a+b=4$、$a-b=3$ 解得 $a=\\frac{7}{2}$，$b=\\frac{1}{2}$。',
        explanation:
          '第一步用平方差公式把 $a^{2}-b^{2}$ 分解为 $(a+b)(a-b)$，于是 $12=(a+b)(a-b)$。把 $a+b=4$ 代入得 $12=4(a-b)$，两边同除以 4 得 $a-b=3$。第二步把 $a+b=4$ 与 $a-b=3$ 相加：$2a=7$，所以 $a=\\frac{7}{2}$；把 $a=\\frac{7}{2}$ 代入 $a+b=4$ 得 $b=4-\\frac{7}{2}=\\frac{1}{2}$。检验：$a+b=\\frac{7}{2}+\\frac{1}{2}=4$，$a^{2}-b^{2}=\\left(\\frac{7}{2}\\right)^{2}-\\left(\\frac{1}{2}\\right)^{2}=\\frac{49}{4}-\\frac{1}{4}=\\frac{48}{4}=12$，完全符合。',
